import React, { createContext, useContext, useReducer } from 'react'
import { combineReducers } from './utility'
import rootReducer from '../state/reducer'

export const EmployeeBenefitsContext = createContext()

export const EBContextProvider = ({ reducer, children }) => {
  return (
    <EmployeeBenefitsContext.Provider
      value={useReducer(combineReducers([reducer, rootReducer]), {})}
    >
      {children}
    </EmployeeBenefitsContext.Provider>
  )
}

export const useEBContextValue = () => useContext(EmployeeBenefitsContext)
