export function isBusinessDay (date) {
  const defaultWorkingWeekdays = [1, 2, 3, 4, 5]
  const workingWeekdays = defaultWorkingWeekdays

  if (workingWeekdays.indexOf(date.day()) >= 0) return true

  return false
};

export function businessDiff (startDate, endDate) {
  const start = startDate < endDate ? startDate : endDate
  const end = endDate > startDate ? endDate : startDate
  let daysBetween = 0

  if (start.isSame(end, 'day')) {
    return daysBetween
  }

  while (start.isBefore(end, 'day')) {
    if (isBusinessDay(start)) {
      daysBetween += 1
    }
    start.add(1, 'd')
  }

  if (!isBusinessDay(end)) {
    daysBetween -= 1
  }

  return daysBetween
};

// Takes a code, for a config type (eg - channels) and returns name against that code.
export function mapCodeToNameFromLeadConfigData (configCode, configTypeName, leadConfigData) {
  if (configTypeName && leadConfigData && configCode) {
    const configData = leadConfigData[configTypeName].find(({ code }) => code === configCode)
    return configData.name
  }
}

