import ebUrls from '../../../../request/urls/employeeBenefit'

export const EB_ACTIONS = {
  RESET_STATE: 'RESET_STATE',
  GCS_UPLOAD_REQUEST: 'GCS_UPLOAD_REQUEST',
  GCS_UPLOAD: 'GCS_UPLOAD',
  PROVIDERS_LIST_REQUEST: 'PROVIDER_LIST_REQUEST',
  PROVIDERS_LIST: 'PROVIDER_LIST',
  LEAD_CONFIG_REQUEST: 'LEAD_CONFIG_REQUEST',
  LEAD_CONFIG: 'LEAD_CONFIG',
  MARKETING_LIST_REQUEST: 'MARKETING_LIST_REQUEST',
  MARKETING_LIST: 'MARKETING_LIST',
  DOWNLOAD_FILE_FROM_GCS_REQUEST: 'DOWNLOAD_FILE_FROM_GCS_REQUEST',
  CLAIM_CONFIG_REQUEST: 'CLAIM_CONFIG_REQUEST',
  CLAIM_CONFIG: 'CLAIM_CONFIG',
  UPLOAD_FILE_STANDALONE_REQUEST: 'UPLOAD_FILE_STANDALONE_REQUEST',
  UPLOAD_FILE_STANDALONE: 'UPLOAD_FILE_STANDALONE',

  // FILE UPLOAD VIEW RELATED ACTIONS
  FILE_UPLOADS_LIST_REQUEST: 'FILE_UPLOADS_LIST_REQUEST',
  FILE_UPLOADS_LIST: 'FILE_UPLOADS_LIST',
  DOWNLOAD_FILE_UPLOADS_REQUEST: 'DOWNLOAD_FILE_UPLOADS_REQUEST',
  DOWNLOAD_FILE_UPLOADS: 'DOWNLOAD_FILE_UPLOADS',
  CANCEL_FILE_REQUEST: 'CANCEL_FILE_REQUEST',
  CANCEL_FILE: 'CANCEL_FILE',
  FILE_DETAIL_REQUEST: 'FILE_DETAIL_REQUEST',
  FILE_DETAIL: 'FILE_DETAIL',
  FILE_ROWS_REQUEST: 'FILE_ROWS_REQUEST',
  FILE_ROWS: 'FILE_ROWS',

  // EXPORT EXCEL

  EXPORT_EXCEL_REQUEST: 'EXPORT_EXCEL_REQUEST',
  EXPORT_EXCEL: 'EXPORT_EXCEL',

  // case quotation remarks
  CASE_QUOTATION_REMARKS_REQUEST: 'CASE_QUOTATION_REMARKS_REQUEST',
  CASE_QUOTATION_REMARKS: 'CASE_QUOTATION_REMARKS',

  resetState: keys => ({
    type: EB_ACTIONS.RESET_STATE,
    payload: keys
  }),
  gcsUpload: (payload) => (
    {
      type: EB_ACTIONS.GCS_UPLOAD_REQUEST,
      payload: {
        ...payload,
        method: 'uploadFileOnGcs',
        signedUrl: ebUrls.generateSignedUrl
      }
    }
  ),
  uploadFileStandAlone: (payload) => ({
    type: EB_ACTIONS.UPLOAD_FILE_STANDALONE_REQUEST,
    payload: {
      ...payload,
      method: 'uploadFile',
      signedUrl: ebUrls.generateSignedUrl
    }
  }),
  getProvidersList: (payload) => (
    {
      type: EB_ACTIONS.PROVIDERS_LIST_REQUEST,
      payload: {
        ...payload,
        method: 'get',
        url: ebUrls.providersList
      }
    }
  ),
  getLeadConfig: (payload) => (
    {
      type: EB_ACTIONS.LEAD_CONFIG_REQUEST,
      payload: {
        ...payload,
        method: 'get',
        url: ebUrls.getLeadConfig
      }
    }
  ),
  updateLeadConfig: (payload) => (
    {
      type: EB_ACTIONS.LEAD_CONFIG,
      payload: {
        leadConfigData: payload
      }
    }
  ),
  updateClaimConfig: (payload) => (
    {
      type: EB_ACTIONS.CLAIM_CONFIG,
      payload: {
        claimConfigData: payload
      }
    }
  ),
  getMarketingList: (payload) => ({
    type: EB_ACTIONS.MARKETING_LIST_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.getMarketing
    }
  }),
  downloadFileFromGcs: payload => ({
    type: EB_ACTIONS.DOWNLOAD_FILE_FROM_GCS_REQUEST,
    payload: {
      ...payload,
      method: 'downloadFileFromGcs',
      signedUrl: ebUrls.generateSignedUrl
    }
  }),
  getClaimConfig: (payload) => ({
    type: EB_ACTIONS.CLAIM_CONFIG_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.getClaimConfig
    }
  }),
  getFileUploadsList: (payload) => ({
    type: EB_ACTIONS.FILE_UPLOADS_LIST_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.fileUploadListCommon
    }
  }),
  downloadFileUploads: payload => ({
    type: EB_ACTIONS.DOWNLOAD_FILE_UPLOADS_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.downloadFileUploads
    }
  }),
  cancelFile: payload => ({
    type: EB_ACTIONS.CANCEL_FILE_REQUEST,
    payload: {
      ...payload,
      method: 'post'
    }
  }),
  getFileDetail: payload => ({
    type: EB_ACTIONS.FILE_DETAIL_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.fileDetail
    }
  }),
  getFileRows: payload => ({
    type: EB_ACTIONS.FILE_ROWS_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.fileRows
    }
  }),
  exportExcel: payload => ({
    type: EB_ACTIONS.EXPORT_EXCEL,
    payload: {
      ...payload,
      method: 'get'
    }
  }),
  caseQuotationRemarks: payload => ({
    type: EB_ACTIONS.CASE_QUOTATION_REMARKS_REQUEST,
    payload: {
      ...payload,
      method: 'get'
    }
  })
}

export const ERROR_ACTIONS = {
  ERROR_UPDATE: 'ERROR_UPDATE',
  STATE_RESET: 'STATE_RESET'
}

export const LOADER_ACTIONS = {
  LOADER_UPDATE: 'LOADER_UPDATE'
}

export const updateLoader = (payload) => ({
  type: LOADER_ACTIONS.LOADER_UPDATE,
  payload
})
